/*
   Save MEP groups without re-reading the whole payments collection.
   Re-read only the documents actually edited, from Firestore server,
   so server timestamps, backend transformations and deleted/missing
   documents are reflected exactly in the updated group.

   The explicit Refresh button continues to do a full-company recheck.
   On any targeted refresh failure, the save handler falls back to the
   original full read rather than showing unverified local edits.

   Firestore `in` supports at most 30 document IDs per query; use 20
   to keep a conservative margin. One initial MEP load is unchanged.
*/
async function refreshEditedMEPGroupFromServer(group){
    const ids = [...new Set(
        (group?.items || []).map(item => String(item?.id || "").trim()).filter(Boolean)
    )];
    if(!ids.length) throw new Error("MEP refresh missing payment IDs");

    const serverRows = new Map();
    for(let i=0;i<ids.length;i+=20){
        const snap = await getDocs(query(
            paymentsRef,
            where(documentId(),"in",ids.slice(i,i+20))
        ));
        snap.forEach(item => {
            serverRows.set(item.id,{id:item.id,...item.data()});
        });
    }

    // Only replace the edited IDs. Non-MEP records are removed just as
    // they would be after the original full-collection refresh.
    const editedIds = new Set(ids);
    const updated = allMEPPayments.filter(row => !editedIds.has(String(row.id)));
    ids.forEach(id => {
        const payment=serverRows.get(id);
        if(payment && isMEPHistoryPayment(payment)) updated.push(payment);
    });
    allMEPPayments=updated;
    buildMEPGroups();
    updateMEPProjectFilter();
    renderMEPMaster();
    mepPaymentsLoaded=true;
    console.info("[Payment Read Audit] MEP edit targeted refresh",{
        editedDocumentCount:ids.length,
        fetchedDocumentCount:serverRows.size,
        fullCompanyReloadAvoided:true
    });
}

closeMEPEdit();
