/*
   Export Watch fallback when (paymentMonth, createdAt) composite index
   has not been created. Compare cheap Firestore aggregate counts before
   choosing the smaller of two COMPLETE candidate sets:
   A) logs from the selected month, or
   B) logs after the last Excel export timestamp.
   Filter and sort in memory to match the original scoped query exactly.
   No partial caps: read every page before building Export Watch changes.
*/
async function readExportWatchFallback(context, markerMs, cutoffMs){
    let mode="time";
    if(context.month !== "ALL"){
        try{
            const [monthCount,timeCount]=await Promise.all([
                getCountFromServer(query(activityLogsRef,
                    where("paymentMonth","==",context.month)
                )),
                getCountFromServer(query(activityLogsRef,
                    where("createdAt",">",new Date(markerMs)),
                    ...(cutoffMs == null ? [] : [where("createdAt","<=",new Date(cutoffMs))])
                ))
            ]);
            if(monthCount.data().count < timeCount.data().count) mode="month";
        }catch(error){
            // Conservative fallback: use exactly the old indexed date scan.
            console.warn("Export Watch read estimates unavailable",error);
        }
    }
    const rows=[];
    let cursor=null;
    for(;;){
        const constraints= mode === "month"
            ? [where("paymentMonth","==",context.month)]
            : [where("createdAt",">",new Date(markerMs))];
        if(mode === "time"){
            if(cutoffMs != null) constraints.push(where("createdAt","<=",new Date(cutoffMs)));
            constraints.push(orderBy("createdAt","asc"));
        }
        if(cursor) constraints.push(startAfter(cursor));
        constraints.push(limit(500));
        const snapshot=await getDocs(query(activityLogsRef,...constraints));
        rows.push(...snapshot.docs.map(item=>({...item.data(),id:item.id})));
        if(snapshot.docs.length < 500) break;
        cursor=snapshot.docs[snapshot.docs.length-1];
    }
    if(mode === "month"){
        // Firestore Timestamps have nanosecond precision. Comparing Date
        // milliseconds alone could silently drop changes at the marker edge.
        const nanos=log=>{
            const value=log?.createdAt;
            if(value && typeof value.seconds === "number"){
                return BigInt(Math.floor(value.seconds))*1000000000n +
                    BigInt(Math.floor(value.nanoseconds || 0));
            }
            const date=exportWatchLogDate(log);
            return date ? BigInt(date.getTime())*1000000n : null;
        };
        const after=BigInt(markerMs)*1000000n;
        const before=cutoffMs == null ? null : BigInt(cutoffMs)*1000000n;
        return rows.filter(log=>{
            const ns=nanos(log);
            return ns !== null && ns > after && (before === null || ns <= before);
        }).sort((a,b)=>{
            const x=nanos(a),y=nanos(b);
            if(x !== y) return x < y ? -1 : 1;
            // Match Firestore's implicit document-ID tie-breaker, not locale collation.
            const ai=String(a.id),bi=String(b.id);
            return ai < bi ? -1 : ai > bi ? 1 : 0;
        });
    }
    if(context.month !== "ALL"){
        return rows.filter(log=>String(log.paymentMonth || "") === context.month);
    }
    return rows;
}

